-- Product-Wise Sales With Product Name


select
  p.ProductID,
 p.ProductName, 
 sum(oi.Total) as totalsale
from `e1.products` as p
inner join `e1.order_items` as oi
on p.ProductID = oi.ProductID
group by p.ProductName,  p.ProductID
order by totalsale desc;


-- CategoryName-Wise total Sales

select
 c.CategoryID,
 c.CategoryName,
 sum(oi.Total) as totalsale
from `e1.products` as p
inner join `e1.categories` as c
on p.CategoryID = c.CategoryID
inner join `e1.order_items` as oi
on p.ProductID = oi.ProductID
group by 
 c.CategoryID,
 c.CategoryName


-- calculate total sales generated by products from each supplier
select  
s.SupplierID,
s.SupplierName,
sum(oi.Total)
from `e1.products` as p
inner join `e1.order_items` as oi
on p.ProductID  = oi.ProductID
inner join `e1.suppliers` as s
on s.SupplierID = p.SupplierID
group by 
 s.SupplierID,
s.SupplierName




select *
from `e1.suppliers`

select *
from `e1.order_items`





